// Validar e extrair filtros do request
const body = $input.first().json.body || $input.first().json;

const cnaeCodes = body.cnaeCodes || [];
const states = body.states || [];
const capitalMin = parseInt(body.capitalMin) || 0;
const capitalMax = parseInt(body.capitalMax) || 10000000;
const excludeMei = body.excludeMei !== false;
const targetCount = parseInt(body.targetCount) || 150;

if (cnaeCodes.length === 0) {
  throw new Error('Nenhum codigo CNAE informado. Selecione pelo menos um segmento.');
}

return [{
  json: {
    cnaeCodes,
    states,
    capitalMin,
    capitalMax,
    excludeMei,
    targetCount,
    totalCnaes: cnaeCodes.length,
    currentCnaeIndex: 0,
    currentPage: 1,
    allCompanies: [],
    seenCnpjs: []
  }
}];

// Construir payload para Casa dos Dados API
const data = $input.first().json;
const cnae = data.cnaeCodes[data.currentCnaeIndex];

const payload = {
  query: {
    termo: [],
    atividade_principal: [cnae],
    natureza_juridica: [],
    uf: data.states.length > 0 ? data.states : [],
    municipio: [],
    situacao_cadastral: 'ATIVA'
  },
  range_query: {
    capital_social: {
      gte: data.capitalMin,
      lte: data.capitalMax
    }
  },
  extras: {
    somente_mei: false,
    excluir_mei: data.excludeMei,
    com_email: false,
    incluir_atividade_secundaria: false,
    com_contato_telefonico: true
  },
  page: data.currentPage
};

return [{
  json: {
    ...data,
    currentCnae: cnae,
    requestPayload: payload
  }
}];

// Processar resposta e acumular empresas
const prev = $('3. Montar Query CNAE').first().json;
const response = $input.first().json;

const companies = response?.data?.cnpj || [];
const allCompanies = [...(prev.allCompanies || [])];
const seenCnpjs = new Set(prev.seenCnpjs || []);

let newCount = 0;
for (const company of companies) {
  const cleanCnpj = (company.cnpj || '').replace(/\D/g, '');
  if (!cleanCnpj || seenCnpjs.has(cleanCnpj)) continue;
  seenCnpjs.add(cleanCnpj);
  newCount++;

  allCompanies.push({
    cnpj: cleanCnpj,
    razao_social: company.razao_social || '',
    nome_fantasia: company.nome_fantasia || '',
    cnae_fiscal_descricao: company.cnae_fiscal_descricao || '',
    cnae_fiscal: company.cnae_fiscal || '',
    uf: company.uf || '',
    municipio: company.municipio || '',
    logradouro: company.logradouro || '',
    numero: company.numero || '',
    bairro: company.bairro || '',
    capital_social: company.capital_social || 0,
    porte: company.porte || '',
    data_inicio_atividade: company.data_inicio_atividade || '',
    telefone1: company.ddd_telefone_1 || company.telefone1 || '',
    telefone2: company.ddd_telefone_2 || company.telefone2 || '',
    email: company.correio_eletronico || company.email || '',
    qsa: (company.qsa || []).map(s => ({
      nome_socio: s.nome_socio || s.nome || '',
      qualificacao_socio: s.qualificacao_socio || s.qual || ''
    }))
  });
}

// Decidir proxima acao
const hasMorePages = newCount > 0 && prev.currentPage < 10;
const needsMoreResults = allCompanies.length < prev.targetCount;
const hasMoreCnaes = prev.currentCnaeIndex < prev.totalCnaes - 1;

let nextPage = prev.currentPage;
let nextCnaeIndex = prev.currentCnaeIndex;
let continueLoop = false;

if (needsMoreResults && hasMorePages) {
  // Mais paginas do mesmo CNAE
  nextPage = prev.currentPage + 1;
  continueLoop = true;
} else if (needsMoreResults && hasMoreCnaes) {
  // Proximo CNAE
  nextCnaeIndex = prev.currentCnaeIndex + 1;
  nextPage = 1;
  continueLoop = true;
}

return [{
  json: {
    ...prev,
    allCompanies,
    seenCnpjs: Array.from(seenCnpjs),
    currentPage: nextPage,
    currentCnaeIndex: nextCnaeIndex,
    continueLoop,
    totalFound: allCompanies.length,
    lastBatchSize: newCount
  }
}];

// Enriquecer cada empresa com OpenCNPJ para obter socios e telefones
const data = $input.first().json;
const companies = data.allCompanies || [];
const enriched = [];

for (let i = 0; i < companies.length; i++) {
  const company = companies[i];
  const cnpj = company.cnpj.replace(/\D/g, '');

  try {
    const res = await fetch('https://api.opencnpj.org/' + cnpj);
    if (res.ok) {
      const d = await res.json();

      // Extrair socios (QSA)
      const socios = (d.qsa || []).map(s => ({
        nome_socio: s.nome_socio || s.nome || '',
        qualificacao_socio: s.qualificacao_socio || s.qual || ''
      }));

      // Extrair telefones
      const phones = [d.telefone1, d.telefone2, d.ddd_telefone_1, d.ddd_telefone_2, d.telefone]
        .filter(Boolean)
        .flatMap(p => p.split(/[\/;,]/))
        .map(p => p.trim().replace(/\D/g, ''))
        .filter(p => p.length >= 10);

      company.qsa = socios.length > 0 ? socios : company.qsa;
      company.telefone1 = phones[0] || company.telefone1;
      company.telefone2 = phones[1] || company.telefone2;
      company.email = d.email || d.correio_eletronico || company.email;
      company.capital_social = d.capital_social || company.capital_social;
      company.nome_fantasia = d.nome_fantasia || company.nome_fantasia;
    }
  } catch (err) {
    // OpenCNPJ falhou — manter dados originais
  }

  enriched.push(company);

  // Rate limit: 200ms entre requests
  if (i < companies.length - 1) {
    await new Promise(r => setTimeout(r, 200));
  }
}

return [{ json: { companies: enriched, total: enriched.length } }];

// Classificar telefones e extrair decisor de cada empresa
const data = $input.first().json;
const companies = data.companies || [];

function classifyPhone(phone) {
  const digits = phone.replace(/\D/g, '');
  const withoutCountry = digits.startsWith('55') ? digits.slice(2) : digits;
  if (withoutCountry.length === 11 && withoutCountry[2] === '9') return 'mobile';
  if (withoutCountry.length === 10 && withoutCountry[2] === '9') return 'mobile';
  return 'landline';
}

function formatPhone(phone) {
  let digits = phone.replace(/\D/g, '').replace(/^0+/, '');
  const withoutCountry = digits.startsWith('55') ? digits.slice(2) : digits;
  if (withoutCountry.length === 10 && withoutCountry[2] === '9') {
    digits = withoutCountry.slice(0, 2) + '9' + withoutCountry.slice(2);
    return '55' + digits;
  }
  if (digits.length >= 10) return digits.startsWith('55') ? digits : '55' + digits;
  return digits;
}

const results = companies.map(company => {
  // Encontrar decisor no QSA
  const socios = company.qsa || [];
  const decisor = socios.find(s =>
    (s.qualificacao_socio || '').toLowerCase().includes('administrador') ||
    (s.qualificacao_socio || '').toLowerCase().includes('diretor') ||
    (s.qualificacao_socio || '').toLowerCase().includes('presidente')
  ) || socios[0];

  // Classificar telefones
  const phones = [company.telefone1, company.telefone2]
    .filter(Boolean)
    .flatMap(p => p.split(/[\/;,]/))
    .map(p => p.trim().replace(/\D/g, ''))
    .filter(p => p.length >= 10);

  const mobilePhone = phones.find(p => classifyPhone(p) === 'mobile');
  const whatsapp = mobilePhone ? formatPhone(mobilePhone) : '';
  const mainPhone = phones[0] ? formatPhone(phones[0]) : '';

  return {
    cnpj: company.cnpj,
    razao_social: company.razao_social,
    nome_fantasia: company.nome_fantasia,
    cnae_fiscal_descricao: company.cnae_fiscal_descricao,
    cnae_fiscal: company.cnae_fiscal,
    uf: company.uf,
    municipio: company.municipio,
    logradouro: company.logradouro,
    numero: company.numero,
    bairro: company.bairro,
    capital_social: company.capital_social,
    porte: company.porte,
    data_inicio_atividade: company.data_inicio_atividade,
    telefone1: mainPhone,
    telefone2: company.telefone2 || '',
    email: company.email,
    qsa: company.qsa,
    // Campos extraidos
    decisor_nome: decisor?.nome_socio || '',
    decisor_cargo: decisor?.qualificacao_socio || '',
    whatsapp: whatsapp,
    tem_whatsapp: !!whatsapp,
    tem_decisor: !!(decisor?.nome_socio),
    qualidade: (!!whatsapp && !!decisor?.nome_socio) ? 'gold' : (!!whatsapp || !!decisor?.nome_socio) ? 'silver' : 'bronze'
  };
});

// Ordenar: gold primeiro, depois silver, depois bronze
results.sort((a, b) => {
  const order = { gold: 0, silver: 1, bronze: 2 };
  return order[a.qualidade] - order[b.qualidade];
});

return [{ json: { companies: results, total: results.length, stats: {
  total: results.length,
  com_whatsapp: results.filter(r => r.tem_whatsapp).length,
  com_decisor: results.filter(r => r.tem_decisor).length,
  gold: results.filter(r => r.qualidade === 'gold').length,
  silver: results.filter(r => r.qualidade === 'silver').length,
  bronze: results.filter(r => r.qualidade === 'bronze').length
} } }];
